/**
 * Category bucket for the "Add Trigger" catalog in the UI.
 *
 *
 * Derived from the owning RegisteredPlugin's provenance and the interfaces the trigger
 * class implements:
 *
 * * #CORE - trigger is bundled with Kestra (no external plugin location).
 * * #REALTIME - external trigger implementing RealtimeTriggerInterface.
 * * #APP - external trigger, typically implementing PollingTriggerInterface.
 * Core precedence wins over realtime/app so a bundled core trigger (for example Webhook) is CORE even if it otherwise looks like a realtime or polling trigger.
 */
export type TriggerPluginCategory = 'core' | 'realtime' | 'app';

export type TriggerType = 'SCHEDULE' | 'POLLING' | 'REALTIME';

export type Type = 'STRING' | 'SELECT' | 'INT' | 'FLOAT' | 'BOOL' | 'DATETIME' | 'DATE' | 'TIME' | 'DURATION' | 'FILE' | 'JSON' | 'URI' | 'SECRET' | 'ARRAY' | 'MULTISELECT' | 'YAML' | 'EMAIL' | 'FORM' | 'REUSABLE_INPUTS';

