/**
 * API DTO for MCP server creation, update, and retrieval.
 *
 *
 * Decouples the public API contract from the internal McpServer domain object.
 * Read-only fields (`isDefault`, `created`, `updated`) are
 * populated in responses and ignored in request bodies.
 */
export type ApiMcpServerWritable = {
    /**
     * Unique identifier of the MCP server.
     */
    id: string;
    /**
     * Human-readable description of the MCP server.
     */
    description?: string;
    /**
     * Instructions sent to the AI model when using this server.
     */
    instructions?: string;
    /**
     * Visibility of the server.
     */
    serverType?: McpServerServerType;
    /**
     * Authentication type for private servers.
     */
    authType?: McpServerAuthType;
    /**
     * OAuth provider key from micronaut.security.oauth2.clients. Required when authType is OAUTH.
     */
    oauthProvider?: string;
    /**
     * Scopes advertised in the server's RFC 9728 Protected Resource Metadata document. Only meaningful when authType is OAUTH. When null or empty the field is omitted from the PRM document.
     */
    oauthScopesSupported?: Array<string>;
    /**
     * Whether the MCP server is disabled.
     */
    disabled?: boolean;
};

